// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _newOwner) public {
        vm.assume(_newOwner != c.owner());

        vm.prank(c.owner());
        c.transferOwnership(_newOwner);

        assertTrue(c.owner() == _newOwner, "owner should be updated to _newOwner");
    }
}
